import { Action, createReducer, on } from '@ngrx/store';
import { fromConfigActions } from '@store/actions/actions';
import { ConfigState } from '@store/model/config.model';
import { CommonUtil } from '@core/util';
import { ContextResponse } from '@model/network/config/config.model';


export const CONFIG_INITIAL_STATE: ConfigState = {
	hasInitializedOnce: false,
	isFirstTimeSetup: false
};

const reducers = createReducer(
	CONFIG_INITIAL_STATE,
	on(fromConfigActions.fetchContextSuccess, (state: ConfigState, newState: ContextResponse) => {
		return CommonUtil.mergeToCopy(state, {
			...newState,
			hasInitializedOnce: true
		});
	}),
	on(fromConfigActions.fetchContextError, (state: ConfigState) => {
		return CommonUtil.mergeToCopy(state, {
			hasInitializedOnce: true,
			isFirstTimeSetup: false
		});
	})
);

export function configReducer(state: ConfigState, action: Action) {
	return reducers(state, action);
}
