import { Component, HostListener, Inject, ChangeDetectionStrategy } from '@angular/core';
import { Icon } from '@shared/constants/icons.constants';
import { DialogButton, DialogData } from '@shared/component/dialog/dialog.models';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';
import { IconComponent } from '@shared/component/icon/icon.component';
import { SharedImplementationModule } from '@shared/shared-implementation.module';


const DEFAULT_DATA: DialogData = {
	content: 'Placeholder text',
	buttons: [{ text: 'Okay', primary: true }]
};

@Component({
	selector: 'app-dialog',
	templateUrl: './dialog.component.html',
	styleUrls: ['./dialog.component.scss'],
	changeDetection: ChangeDetectionStrategy.Eager,
	imports: [SharedImplementationModule, IconComponent],
})
export class DialogComponent extends AbstractComponent {
	Icon = Icon;

	constructor(@Inject(MAT_DIALOG_DATA) public data: DialogData = {}, private readonly dialogRef: MatDialogRef<DialogComponent>) {
		super();
		const content: string[] = Array.isArray(data.content) ? data.content : [data.content] as string[];
		this.data = { ...DEFAULT_DATA, ...this.data, content };
	}

	private close(value: any): void {
		this.dialogRef.close(value);
	}

	@HostListener('keydown.esc')
	onEscListener(): void {
		this.close(false);
	}

	onClick($event: MouseEvent, button: DialogButton): void {
		if (!!button.onClick) {
			button.onClick($event);
		}
		this.close(button.onCloseValue);
	}

	getButtons(): DialogButton[] {
		return Array.isArray(this.data.buttons) ? this.data.buttons : [this.data.buttons];
	}
}
