import { computed, DestroyRef, DOCUMENT, inject, Injectable, Signal, signal, WritableSignal } from '@angular/core';
import { BoundedLocalStorage } from '@core/service/local-storage.service';
import { THEME_CSS_PREFIX, Themes, ThemeValue } from '@model/common/theme.model';
import { LocalStorageKey } from '@shared/constants/local-storage.constants';

const PREFERS_LIGHT_QUERY = '(prefers-color-scheme: light)';

/**
 * Holds the active theme and applies it to the document body.
 *
 * Dark is the default. A visitor whose browser or OS prefers light gets light, until they pick a theme
 * themselves; that choice is stored and wins from then on.
 */
@Injectable({
	providedIn: 'root'
})
export class ThemeService {
	private static readonly STORAGE: BoundedLocalStorage<ThemeValue> = BoundedLocalStorage.create(LocalStorageKey.THEME);

	private readonly document: Document = inject(DOCUMENT);
	private readonly prefersLightQuery: MediaQueryList | null = this.document.defaultView?.matchMedia?.(PREFERS_LIGHT_QUERY) ?? null;
	private readonly storedTheme: WritableSignal<ThemeValue | null> = signal(ThemeService.readStoredTheme());
	private readonly prefersLight: WritableSignal<boolean> = signal(this.prefersLightQuery?.matches ?? false);

	readonly theme: Signal<ThemeValue> = computed(() => this.storedTheme() ?? (this.prefersLight() ? Themes.LIGHT : Themes.DARK));
	readonly nextTheme: Signal<ThemeValue> = computed(() => this.theme() === Themes.DARK ? Themes.LIGHT : Themes.DARK);

	constructor() {
		const onPreferenceChange = (event: MediaQueryListEvent): void => {
			this.prefersLight.set(event.matches);
			this.applyToDocument(this.theme());
		};
		this.prefersLightQuery?.addEventListener('change', onPreferenceChange);
		inject(DestroyRef).onDestroy(() => this.prefersLightQuery?.removeEventListener('change', onPreferenceChange));

		this.applyToDocument(this.theme());
	}

	setTheme(theme: ThemeValue): void {
		this.storedTheme.set(theme);
		ThemeService.STORAGE.set(theme);
		this.applyToDocument(theme);
	}

	toggleTheme(): void {
		this.setTheme(this.nextTheme());
	}

	private applyToDocument(activeTheme: ThemeValue): void {
		const classList = this.document.body.classList;
		for (const theme of Object.values(Themes)) {
			classList.toggle(`${THEME_CSS_PREFIX}${theme.cssName}`, theme === activeTheme);
		}
	}

	private static readStoredTheme(): ThemeValue | null {
		const stored = ThemeService.STORAGE.get();
		return Object.values(Themes).find(theme => theme.cssName === stored?.cssName) ?? null;
	}
}
