import { ChangeDetectionStrategy, Component } from '@angular/core';
import { PagesModule } from '@pages/pages.module';
import { SITE } from '@app/app.constants';
import packageJson from '../../package.json';

@Component({
	selector: 'app-root',
	templateUrl: './app.component.html',
	styleUrl: './app.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
	imports: [PagesModule]
})
export class AppComponent {
	protected readonly SITE = SITE;
	protected readonly copyright: string = AppComponent.resolveCopyright(packageJson.copyright, new Date().getFullYear());

	/**
	 * Fills in the current year, and collapses a range like "2026-2026" to a single year.
	 */
	private static resolveCopyright(template: string, currentYear: number): string {
		return template
			.replace(/{{\s*currentYear\s*}}/, currentYear.toString())
			.replace(/(\d{4})-\1\b/, '$1');
	}
}
