import { Component, Input, OnChanges, SimpleChanges, ChangeDetectionStrategy } from '@angular/core';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';

import { SharedImplementationModule } from '@shared/shared-implementation.module';


@Component({
	selector: 'app-alert',
	templateUrl: './alert.component.html',
	changeDetection: ChangeDetectionStrategy.Eager,
	imports: [SharedImplementationModule]
})
export class AlertComponent extends AbstractComponent implements OnChanges {
	@Input() type: 'primary' | 'secondary' | 'success' | 'error' | 'warning' | 'info' | 'light' | 'dark' = 'info';
	typeClassName: string = 'info';

	constructor() {
		super();
	}

	ngOnChanges(changes: SimpleChanges): void {
		if (changes['type'].previousValue !== changes['type'].currentValue) {
			this.setTypeClassName();
		}
	}

	private setTypeClassName(): void {
		this.typeClassName = (this.type === 'error') ? 'danger' : this.type;
	}

}
