import { ALL_AUTHENTICATED_PERMISSIONS, Permission } from './permission.constants';
import { TwoWayMap } from '../util/map';
import { MaybeReadonly } from '@core/typing/common.type';

export enum HttpMethod {
	GET = 'GET',
	POST = 'POST',
	PUT = 'PUT',
	DELETE = 'DELETE'
}

type EndpointType = { [key: string] : Endpoint }

export interface Endpoint {
	path: `/${string}`;
	methods?: HttpMethod[];
	permissions?: MaybeReadonly<Permission> | MaybeReadonly<Permission[]>;
	subEndpoints?: EndpointType;
}

export const ENDPOINTS = {
	index: {
		path: '/',
		methods: [HttpMethod.GET],
		permissions: Permission.UNAUTHENTICATED,
		subEndpoints: {
			health: {
				path: '/health',
				methods: [HttpMethod.GET],
				permissions: Permission.UNAUTHENTICATED
			},
			context: {
				path: '/context',
				methods: [HttpMethod.GET],
				permissions: Permission.UNAUTHENTICATED
			}
		}
	},
	auth: {
		path: '/auth',
		subEndpoints: {
			login: {
				path: '/login',
				methods: [HttpMethod.POST],
				permissions: Permission.UNAUTHENTICATED
			},
			logout: {
				path: '/logout',
				methods: [HttpMethod.POST],
				permissions: ALL_AUTHENTICATED_PERMISSIONS
			},
			userSession: {
				path: '/user-session',
				methods: [HttpMethod.POST],
				permissions: ALL_AUTHENTICATED_PERMISSIONS
			}
		}
	}
} satisfies EndpointType;


const ENDPOINTS_BY_PATH: TwoWayMap<string, Endpoint> = new TwoWayMap<string, Endpoint>();
initEndpointsByPathRecursive(undefined, ENDPOINTS);

function initEndpointsByPathRecursive(currentPath: string | undefined, currentEndpoint: EndpointType): void {
	if (currentEndpoint) {
		Object.values(currentEndpoint).forEach((endpoint: Endpoint) => {
			const newPath = currentPath ? currentPath + endpoint.path : endpoint.path;
			if (endpoint.methods?.length) {
				ENDPOINTS_BY_PATH.set(newPath.replace('//', '/'), endpoint);
			}
			initEndpointsByPathRecursive(newPath, endpoint.subEndpoints);
		});
	}
}

export function getEndpointByPath(path: string): Endpoint | null {
	return ENDPOINTS_BY_PATH.get(path);
}

export function getPathByEndpoint(endpoint: Endpoint): string | null {
	return ENDPOINTS_BY_PATH.revGet(endpoint);
}

export function getAllEndpointsPaths(): string[] {
	return [...ENDPOINTS_BY_PATH.keys()].sort((a: string, b: string) => a.localeCompare(b));
}
