import { ChangeDetectionStrategy, Component } from '@angular/core';
import { FaIconComponent } from '@fortawesome/angular-fontawesome';
import { faGithub } from '@fortawesome/free-brands-svg-icons';
import { SITE } from '@app/app.constants';
import { PageSection } from '@shared/constants/routing-paths.constants';
import { PROJECTS } from '@pages/home/home.constants';

@Component({
	selector: 'app-home',
	templateUrl: './home.component.html',
	styleUrl: './home.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
	imports: [FaIconComponent]
})
export class HomeComponent {
	protected readonly SITE = SITE;
	protected readonly PageSection = PageSection;
	protected readonly projects = PROJECTS.map(project => ({ ...project, tagLine: project.tags.join(' · ') }));
	protected readonly faGithub = faGithub;
}
