import { Injectable } from '@angular/core';


@Injectable({
	providedIn: "root"
})
export class LocalStorage<T = any> {

	/**
	 * Return a local storage service instance that is bounded by the key.
	 * @param storageKey The key to bound the local storage service too.
	 */
	toBounded(storageKey: string): BoundedLocalStorage<T> {
		return new BoundedLocalStorage<T>(this, storageKey);
	}

	set(key: string, value: T): void {
		if (value instanceof String) {
			localStorage.setItem(key, value as string);
		} else if (value instanceof Object || Array.isArray(value)) {
			localStorage.setItem(key, JSON.stringify(value));
		} else {
			localStorage.setItem(key, String(value));
		}
	}

	getItem<K extends keyof T>(storageKey: string, key: K): T[K] | null {
		return this.get(storageKey)?.[key];
	}

	setItem<K extends keyof T>(storageKey: string, keyOrFn: K, value: T[K]): void;
	setItem(storageKey: string, keyOrFn: ((previousStorage: T | null) => T)): void;
	setItem<K extends keyof T>(storageKey: string, keyOrFn: K | ((previousStorage: T | null) => T), value: T[K] = null): void {
		const previousState = this.get(storageKey);

		if (typeof keyOrFn === 'function') {
			this.set(storageKey, keyOrFn(previousState));
		} else {
			this.set(storageKey, {
				...previousState,
				[keyOrFn]: value
			});
		}
	}

	get(key: string): T | null {
		const valueAsString = localStorage.getItem(key);
		if (valueAsString == null) {
			return null;
		}

		return LocalStorage.castStringToProperty(valueAsString);
	}

	protected static castStringToProperty(value: string): any {
		if (new RegExp('^(true|false)$').exec(value)) {
			return LocalStorage.toBoolean(value);
		} else if (!Number.isNaN(+value)) {
			return Number(value);
		} else if (!value) {
			return value;
		}

		try {
			return JSON.parse(value);
		} catch (e) {
			console.error(e);
			return value;
		}
	}

	remove(key: string): void {
		localStorage.removeItem(key);
	}

	removeItem<K extends keyof T>(storageKey: string, key: K): void {
		this.setItem(storageKey, key, null);
	}

	/**
	 * Because Boolean('false') returns true...
	 */
	private static toBoolean(value: string): boolean {
		return value === 'true';
	}

}

/**
 * LocalStorageService implementation that is bounded by a fixed local storage key.
 */
export class BoundedLocalStorage<T> {

	constructor(protected readonly localStorageService: LocalStorage<T>, protected readonly storageKey: string) {}

	static create<T>(key: string, localStorageService: LocalStorage = new LocalStorage()): BoundedLocalStorage<T> {
		return new BoundedLocalStorage<T>(localStorageService, key);
	}

	set(value: T): void	{
		this.localStorageService.set(this.storageKey, value);
	}

	getItem<K extends keyof T>(key: K): T[K] | null {
		return this.localStorageService.getItem(this.storageKey, key);
	}

	setItem<K extends keyof T>(keyOrFn: K, value: T[K]): void;
	setItem(keyOrFn: ((previousStorage: T | null) => T)): void;
	setItem<K extends keyof T>(keyOrFn: K | ((previousStorage: T | null) => T), value: T[K] = null): void {
		if (typeof keyOrFn === 'function') {
			this.localStorageService.setItem(this.storageKey, keyOrFn);
		} else {
			this.localStorageService.setItem(this.storageKey, keyOrFn, value);
		}
	}

	get(): T | null	{
		return this.localStorageService.get(this.storageKey);
	}

	remove(): void {
		this.localStorageService.remove(this.storageKey);
	}

	removeItem<K extends keyof T>(key: K): void {
		this.localStorageService.removeItem(this.storageKey, key);
	}

}
