import { ChangeDetectionStrategy, Component, computed, inject, Signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { MatIconButton } from '@angular/material/button';
import { MatIcon } from '@angular/material/icon';
import { MatTooltip } from '@angular/material/tooltip';
import { PageSection, Route } from '@shared/constants/routing-paths.constants';
import { ThemeService } from '@core/service/theme.service';
import { SITE } from '@app/app.constants';

@Component({
	selector: 'app-toolbar',
	templateUrl: './toolbar.component.html',
	styleUrl: './toolbar.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
	imports: [RouterLink, MatIconButton, MatIcon, MatTooltip]
})
export class ToolbarComponent {
	private readonly themeService: ThemeService = inject(ThemeService);

	protected readonly Route = Route;
	protected readonly PageSection = PageSection;
	protected readonly SITE = SITE;

	protected readonly themeIcon: Signal<string> = computed(() => this.themeService.theme().icon);
	protected readonly themeSwitchLabel: Signal<string> = computed(() => `Switch to ${this.themeService.nextTheme().displayText} theme`);

	protected toggleTheme(): void {
		this.themeService.toggleTheme();
	}
}
