import { Injectable } from '@angular/core';
import { Store } from '@ngrx/store';
import { HttpClient } from '@angular/common/http';
import { BoundedLocalStorage, LocalStorage } from '@core/service/local-storage.service';
import { BehaviorSubject, finalize, Observable, of, tap, throwError } from 'rxjs';
import { fromAuthSelectors } from '@store/selectors/selectors';
import { fromAuthActions } from '@store/actions/actions';
import {
	LoginRequest,
	LoginResponse,
	LogoutRequest,
	LogoutResponse,
	RegisterRequest,
	RegisterResponse,
	UserSession,
	UserSessionRequest,
	UserSessionResponse
} from '@core/model/network/auth/auth.model';
import { AuthStatus } from '@core/model/network/response.model';
import { verifyResponseBodyStatus } from '@core/util';
import { LocalStorageKey } from '@shared/constants/local-storage.constants';
import { AuthStorage } from '@app/app.model';
import { Permission } from '@core/constants';


const defaultUser: LoginResponse = {
	status: AuthStatus.VALID_AUTH,
	validUntil: Date.now() + 9999999999,
	user: {
		username: 'admin',
		email: 'test@test.com',
		firstName: 'admin',
		lastName: 'admin',
	},
	permissions: [Permission.AUTHENTICATED],
	token: 'token-placeholder'
};

const invalidAuthResponse: Readonly<LoginResponse> = {
	status: AuthStatus.INVALID_AUTH
};


@Injectable({
	providedIn: 'root'
})
export class AuthService {
	private loggedInUser?: UserSession;
	private readonly isUserAuthenticatedSubject: BehaviorSubject<boolean> = new BehaviorSubject<boolean>(false);
	private static readonly LOCAL_STORAGE_TOKEN_KEY: string = 'token';
	private readonly storage: BoundedLocalStorage<AuthStorage>;

	constructor(private readonly store: Store, private readonly http: HttpClient, storage: LocalStorage) {
		this.storage = storage.toBounded(LocalStorageKey.AUTH);
		this.store.select(fromAuthSelectors.selectUserSession)
			.subscribe((userSession: UserSession) => {
				this.loggedInUser = userSession;
				this.isUserAuthenticatedSubject.next(this.isAuthenticated());
			});
	}

	login(request: LoginRequest): Observable<LoginResponse> {
		// TODO: Missing functionality. Implement?
		return of(invalidAuthResponse).pipe(
			 tap((response: LoginResponse) => verifyResponseBodyStatus(response))
		);

		// return of({
		// 	...defaultUser,
		// 	status: AuthStatus[request.username] || AuthStatus.VALID_AUTH,
		// 	validUntil: Date.now() + 9999999999,
		// 	user: {
		// 		...defaultUser.user
		// 	}
		// } as LoginResponse).pipe(
		// 	tap((response: LoginResponse) => verifyResponseBodyStatus(response))
		// );

		// return this.http.post<LoginResponse>(ApiEndpoint.LOGIN, request).pipe(
		// 	 tap((response: LoginResponse) => verifyResponseBodyStatus(response))
		// );
	}

	register(registerRequest: RegisterRequest): Observable<RegisterResponse> {
		// TODO: Missing functionality. Implement?
		return of(invalidAuthResponse).pipe(
			tap((response: LoginResponse) => verifyResponseBodyStatus(response))
		);

		// return this.http.post<RegisterResponse>(ApiEndpoint.REGISTER, registerRequest).pipe(
		// 	tap(verifyResponseBodyStatus)
		// );
	}

	logout(request: LogoutRequest): Observable<LogoutResponse> {
		return of({
			status: AuthStatus.VALID_AUTH
		}).pipe(
			finalize(() => {
				this.deleteUserTokenFromLocalStorage();
			})
		);

		// return this.http.post<LogoutResponse>(ApiEndpoint.LOGOUT, request).pipe(
		// 	finalize(() => {
		// 		this.deleteUserTokenFromLocalStorage();
		// 	})
		// );
	}

	getUserSession(request: UserSessionRequest = { token: this.getUserTokenFromLocalStorage() }): Observable<UserSessionResponse> {
		// return this.http.post<UserSessionResponse>(ApiEndpoint.GET_USER_SESSION, request).pipe(
		// 	tap(verifyResponseBodyStatus),
		// 	switchMap((response: UserSessionResponse) => this.verifyTokenValidity(response))
		// );

		// TODO: Missing functionality. Implement?
		return of(invalidAuthResponse).pipe(
			tap((response: LoginResponse) => verifyResponseBodyStatus(response))
		);
	}

	hasSessionToken(): boolean {
		return !!this.loggedInUser?.token;
	}

	getSessionToken(): string {
		return this.loggedInUser?.token;
	}

	isSessionTokenValid(userSession: UserSession = this.loggedInUser): boolean {
		const validUntil = userSession?.validUntil;
		return validUntil ? validUntil > Date.now() : false;
	}

	isAuthenticated(): boolean {
		return this.hasSessionToken() && this.isSessionTokenValid();
	}

	verifyTokenValidity<T extends { token?: string; }>(response: T): Observable<T> {
		if (!response?.token) {
			return throwError(() => ({ status: AuthStatus.ERROR, message: 'Token not found. Validity could not be verified'}))
		} else if (!this.isSessionTokenValid(response)) {
			return throwError(() => ({ ...response, status: AuthStatus.INVALID_AUTH, message: 'Token has expired' }));
		}
		return of(response);
	}

	getUserAuthenticatedSubject(): BehaviorSubject<boolean> {
		return this.isUserAuthenticatedSubject;
	}

	removeUserSessionLocally(): void {
		this.storage.remove();
		this.store.dispatch(fromAuthActions.logoutSuccess({ status: AuthStatus.VALID_AUTH }));
	}

	setUserTokenFromLocalStorage(token: string): void {
		return this.storage.setItem('token', token);
	}

	getUserTokenFromLocalStorage(): string | null {
		return this.storage.getItem('token') || null;
	}

	deleteUserTokenFromLocalStorage(): void {
		this.storage.removeItem('token');
	}

	setRememberSession(value: boolean): void {
		return this.storage.setItem('rememberMe', value);
	}

	shouldRememberSession(): boolean {
		return this.storage.getItem('rememberMe') ?? false;
	}

	getUserPermissions(): Permission[] {
		return [...this.loggedInUser?.permissions ?? []];
	}

}
