/**
 * Theme properties.
 */
export interface Theme {
	/**
	 * The text displayed for the user
	 */
	displayText: string;

	/**
	 * The material icon for the theme
	 */
	icon: string;

	/**
	 * The CSS class name for the theme (excluding the {@link THEME_CSS_PREFIX} prefix).
	 */
	cssName: string;
}

/**
 * Define the possible themes and names.
 */
export const Themes = {
	DARK: {
		displayText: 'dark',
		icon: 'dark_mode',
		cssName: 'dark-1'
	},
	LIGHT: {
		displayText: 'light',
		icon: 'light_mode',
		cssName: 'light-1'
	},
} as const satisfies Record<string, Theme>;


/**
 * CSS class prefix for all themes.
 */
export const THEME_CSS_PREFIX = 'theme-'

/**
 * A type for all {@link Themes} type keys.
 */
export type ThemeKey = keyof typeof Themes;

/**
 * A type for all {@link Themes} type values.
 */
export type ThemeValue = typeof Themes[keyof typeof Themes];

/**
 * A type for other functions that requires all {@link Themes} keys and custom values to be provided.
 */
export type ThemeProvider<ValueType = any> = Record<ThemeKey, ValueType>;

/**
 * Convert a value to a theme reference, or null if none matched.
 */
export function asTheme(value: any): ThemeValue | null {
	return Themes[value] ?? null;
}
