import { Routes } from '@angular/router';
import { Route } from '@shared/constants/routing-paths.constants';
import { AuthGuard } from '@core/guard/auth.guard';
import { HomeComponent } from '@pages/home/home.component';
import { SettingsComponent } from '@pages/settings/settings/settings.component';
import { LoginComponent } from '@pages/auth/login/login.component';
import { RegisterComponent } from '@pages/auth/register/register.component';
import { NoAuthGuard } from '@core/guard/no-auth.guard';

export const ROUTES: Routes = [
	{	// Specific to browse ALL
		path: Route.toPath(Route.HOME),
		component: HomeComponent,
	},
	{
		path: Route.toPath(Route.LOGIN),
		canActivate: [NoAuthGuard],
		component: LoginComponent,
	},
	{
		path: Route.toPath(Route.REGISTER),
		canActivate: [NoAuthGuard],
		component: RegisterComponent,
	},
	{
		path: Route.toPath(Route.SETTINGS.ALL),
		canActivate: [AuthGuard],
		component: SettingsComponent,
	},
	// Fallback when no prior routes is matched
	{ path: "**", redirectTo: Route.toPath(Route.HOME), pathMatch: "full" }
];