import { Object as TsObject, Function, String } from 'ts-toolbelt';
import { cloneDeep } from 'lodash-es';
import { parse } from 'tinyduration';

export type MutableShallow<T> = { -readonly [P in keyof T]: T[P] }; // Only one layer
export type Mutable<T> = { -readonly [P in keyof T]: Mutable<T[P]> };

export function first<T>(array: T[]): T {
	return array[0];
}

export function last<T>(array: T[]): T {
	return array[array.length - 1];
}

/**
 * Returns a mutable, and cloned object
 * @param source Object to clone
 */
export function deepClone<T>(source: Readonly<T>): T {
	return cloneDeep(source) as Mutable<T> as any;
}

export declare function getByPropertyPath<Obj extends object, Path extends string>(
	object: Obj, path: Function.AutoPath<Obj, Path>
): TsObject.Path<Obj, String.Split<Path, '.'>>


type StringKey<T> =
	T extends readonly unknown[]
		? number extends T['length']
			? number : `${number}`
		: string | number;

export type PropertyPath<T> =
	T extends object
		? {
			[P in keyof T & StringKey<T>]: `${P}` | `${P}.${PropertyPath<T[P]>}`;
		}[keyof T & StringKey<T>]
		: never;

export type DeepPartial<T> = {
	[P in keyof T]?: DeepPartial<T[P]>;
};

/**
 * Converts from the duration format to milliseconds.
 * WARNING: Doesn't support converting from years (no duration should be this long anyway...)!
 * @param value To convert
 */
export function parseDurationToMillis(value: string): number {
	const monthsMillis = 2629800000;
	const weekMillis = 604800000;
	const dayMillis = 86400000;
	const hourMillis = 3600000;
	const minuteMillis = 60000;
	const secondMillis = 1000;

	const parsedValue = parse(value) || {};
	return (parsedValue.months * monthsMillis || 0)
		+ (parsedValue.weeks * weekMillis || 0)
		+ (parsedValue.days * dayMillis || 0)
		+ (parsedValue.hours * hourMillis || 0)
		+ (parsedValue.minutes * minuteMillis || 0)
		+ (parsedValue.seconds * secondMillis || 0);
}

/**
 * Numeric enums typically contains {@link https://www.typescriptlang.org/docs/handbook/enums.html#reverse-mappings reverse mappings} as well.
 * This function extracts the values to only keep the numeric values.
 * @param enumLike The enum to extract the numeric values from.
 */
export function getNumericValuesOfEnum(enumLike: { [key: string]: number | string }): number[] {
	return Object.values(enumLike).filter(value => typeof value === 'number');
}

/**
 * Wrap a value as a readonly type.
 */
export function asReadonly<T>(value: T): Readonly<T> {
	return value;
}
