import { Component, ChangeDetectionStrategy } from '@angular/core';
import { Router } from '@angular/router';
import { Route } from '@shared/constants/routing-paths.constants';
import { Store } from '@ngrx/store';
import * as fromAuthActions from '@store/actions/auth.actions';
import { FormControl, FormGroup, ValidationErrors, Validators } from '@angular/forms';
import { LoginFormGroup } from '@pages/auth/login/login.model';
import { LoginResponse } from '@model/network/auth/auth.model';
import { AuthStatus } from '@model/network/response.model';
import { PagesModule } from '@pages/pages.module';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';
import { Logger } from '@core/service/logger.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss'],
	changeDetection: ChangeDetectionStrategy.Eager,
	imports: [PagesModule]
})
export class LoginComponent extends AbstractComponent {
	returnUrl: Route;
	formGroup: FormGroup<LoginFormGroup> = new FormGroup<LoginFormGroup>({
		username: new FormControl<string>('', Validators.required),
		password: new FormControl<string>('', Validators.required),
		rememberMe: new FormControl<boolean>(true),
		unrecoverableError: new FormControl<any>(undefined, () => this.unrecoverableErrorValidator())
	});
	errorResponse?: LoginResponse;

	constructor(private readonly router: Router,
							private readonly store: Store) {
		super();
		this.returnUrl = this.getReturnUrl();
	}

	private getReturnUrl(): Route {
		const stateReturnUrl = this.router.currentNavigation?.()?.extras?.state?.['returnUrl'];
		return Route.asRoute(stateReturnUrl) ?? Route.HOME;
	}

	onSubmit(): void {
		if (this.formGroup.valid) {
			this.store.dispatch(fromAuthActions.login({
				request: {
					username: this.formGroup.controls.username.value,
					password: this.formGroup.controls.password.value,
					rememberMe: !!this.formGroup.controls.rememberMe?.value
				},
				redirectUrl: this.returnUrl
			}));
		} else {
			Logger.logComponent(this.constructor.name, 'Login form not valid');
		}

		// TODO: Add logic in the UI (missing store functionality). Login currently not added in the backend.
		// TODO: On success => Redirect the user
		// TODO: On failure => Show error (set 'errorMessage' variable)
	}

	getLoginResponseErrorMessage(): string {
		switch (this.errorResponse?.status) {
			case AuthStatus.INVALID_AUTH:
				return 'Invalid username or password. Please try again';
			case AuthStatus.TOO_MANY_ATTEMPTS:
				return 'The many sign in attempts have been done. Please try again later'
			case AuthStatus.INSUFFICIENT_PERMISSIONS:
				return `The user doesn't have sufficient permissions to sign in to the UI`;
			default:
				return 'Something went wrong when contacting the server. Perhaps the connection has been dropped?'
		}
	}

	/**
	 * Ensures the form remains "invalid" when there's an error that doesn't allow the user to try to submit the form.
	 */
	unrecoverableErrorValidator(): ValidationErrors | null {
		return this.errorResponse?.status === AuthStatus.TOO_MANY_ATTEMPTS ? { error: true } : null;
	}

}
