import { createFeatureSelector, createSelector } from '@ngrx/store';
import { AuthState } from '@store/model/app.model';
import { ConfigState } from '@store/model/config.model';

export const selectConfig = createFeatureSelector<ConfigState>('config');

export const hasInitializedOnce = createSelector(
	selectConfig,
	(state: ConfigState) => state?.hasInitializedOnce ?? false
);


export const isFirstTimeSetup = createSelector(
	selectConfig,
	(state: ConfigState) => state?.isFirstTimeSetup ?? false
);
