export enum Permission {
	UNAUTHENTICATED = 'UNAUTHENTICATED',
	AUTHENTICATED = 'AUTHENTICATED',
	USER_EDIT = 'USER_EDIT',
	USER_EXTENDED = 'USER_EXTENDED',
	ADMIN = 'ADMIN'
}

export const ALL_AUTHENTICATED_PERMISSIONS: Readonly<Permission[]> = [
	...Object.values(Permission).filter(item => item !== Permission.UNAUTHENTICATED)
];

export function hasPermission(userPermissions: Permission[], anyOf: (Permission | string)[]): boolean {
	return !!userPermissions?.find(userPermission => anyOf.includes(userPermission));
}
