import { Injectable } from '@angular/core';
import { map, of, switchMap } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { fromConfigActions } from '@store/actions/actions';
import { Actions, createEffect, ofType } from '@ngrx/effects';
import { NotificationService } from '@core/service/notification.service';
import { Router } from '@angular/router';
import { Logger } from '@core/service/logger.service';
import { ConfigService } from '@core/service/config.service';
import { ContextResponse } from '@model/network/config/config.model';

@Injectable()
export class ConfigEffects {

	constructor(private actions$: Actions,
							private configService: ConfigService,
							private notificationService: NotificationService,
							private router: Router) {
	}

	fetchContext$ = createEffect(() =>
		this.actions$.pipe(
			ofType(fromConfigActions.fetchContext),
			switchMap(() => this.configService.getContext().pipe(
				map((response: ContextResponse) => {
					return fromConfigActions.fetchContextSuccess(response)
				}),
				catchError((error) => {
					Logger.logStoreEffects(ConfigEffects.name, 'Error for fetchContext$:', error);
					return of(fromConfigActions.fetchContextError(error))
				})
			))
		));

}