import { ChangeDetectionStrategy, Component, computed, Input, input, InputSignal, OnInit, signal, Signal, TemplateRef, WritableSignal } from '@angular/core';
import { ControlContainer, FormControl, FormGroupDirective } from '@angular/forms';
import { CustomInputLiterals } from '@shared/component/mat-custom-input/mat-custom-input.model';
import { CUSTOM_INPUT_LITERAL_DEFAULTS } from '@shared/component/mat-custom-input/mat-custom-input.constants';
import { ValidationService } from '@shared/service/validation.service';
import { CommonUtil } from '@core/util';
import { AbstractComponent } from '@shared/component/abstract-component/abstract-component';
import { SharedImplementationModule } from '@shared/shared-implementation.module';
import { MaterialModule } from '@app/material.module';

@Component({
  selector: 'app-mat-custom-input',
  templateUrl: './mat-custom-input.component.html',
  styleUrls: ['./mat-custom-input.component.scss'],
	providers: [
		{ provide: ControlContainer, useExisting: FormGroupDirective },
	],
	imports: [SharedImplementationModule, MaterialModule]
})
export class MatCustomInputComponent extends AbstractComponent implements OnInit {

	// Required
	control: InputSignal<FormControl | string> = input.required();

	// Optional
	literals: InputSignal<CustomInputLiterals | null> = input(null);
	protected resolvedLiterals: Signal<CustomInputLiterals> = computed(() => {
		const candidate = CommonUtil.mergeToCopy(CUSTOM_INPUT_LITERAL_DEFAULTS, this.literals())
		if (CommonUtil.isNotDefined(candidate.valuePlaceholder)) {
			candidate.valuePlaceholder = candidate.label;
		}
		return candidate;
	});
	maskValues: InputSignal<boolean> = input(false);
	enableResetBtn: InputSignal<boolean> = input(true);
	enableVisibilityBtn?: InputSignal<boolean> = input(true);
	removePadding?: InputSignal<boolean> = input(false);
	hintTemplateRef?: InputSignal<TemplateRef<any> | null> = input(null);
	enableLabel: InputSignal<boolean> = input<boolean>(true);
	protected label: string = '';
	protected placeholder: string = '';

	formControl: FormControl<any>;
	isHidden: WritableSignal<boolean> = signal(false);

	constructor(private readonly rootFormGroup: FormGroupDirective) {
		super();
	}

	ngOnInit(): void {
		const controlValue = this.control();
		this.formControl = CommonUtil.isString(controlValue) ? this.rootFormGroup?.control?.get(controlValue) as FormControl<any> : controlValue;
		this.isHidden.set(this.maskValues());
	}

	toggleHideInput(): void {
		this.isHidden.set(!this.isHidden);
	}

	getValidationErrorMessage(): string {
		return ValidationService.getValidationErrorMessage(this.formControl.errors, this.resolvedLiterals()?.validationErrors);
	}

}
