import { ApiResponse, AuthStatus, ExecutionStatus } from '@core/model/network/response.model';


const VALID_STATUSES = new Set([AuthStatus.VALID_AUTH, ExecutionStatus.SUCCESS])

// TODO: Check if 'T' generic can be used. Currently it's converted to another observable type despite having the 'any' return type
/**
 * Verifies the response body has a successful status code attached to it.
 * If not, an error is thrown.
 * @param response The response body to inspect
 */
export function verifyResponseBodyStatus<T extends ApiResponse>(response: any): T {
	console.log('RESPONSE', response);
	if (!VALID_STATUSES.has(response?.status)) {
		if (AuthStatus.INVALID_AUTH === response?.status) {
			throw new Error('Invalid user credentials');
		} else if (AuthStatus.INSUFFICIENT_PERMISSIONS === response?.status) {
			throw new Error('User does not have sufficient permissions to do this operation');
		}

		throw new Error(`Invalid response body status: [${response?.status}]`);
	}
	return response;
}
